// P11 lockstep: rtl/v3 RTL against its gate-level netlist (module renamed lfu_cache_controller_gl by
// tools/p5f_wrap.py; cell models generated by Yosys from the NanGate45 liberty, results/P5f_gls/models).
// Functional gate-level simulation, zero delay: no SDF, no timing.
// Stimulus: the trace replay of synthesis/p9/tb_hitlog.sv with STIM = 1, FULL = 1 (same code and seed): one
// request outstanding, the next request on the falling edge after the response, fill 0-3 cycles after fill_req
// (random, seed SEED), random fill data; the handshake is keyed on the RTL's outputs. Every cycle after reset
// release, all outputs are compared with !== as in synthesis/p5f/tb_gls_lockstep.sv: hit_flag, resp_valid,
// resp_data, fill_req, fill_addr; every output of both designs is checked for X/Z (XOR reduction === 1'bx).
// +hitlog=<file>: one line `<request index> <address hex> <hit_flag>` per request, from the RTL (same format as
// tb_hitlog, so it can be compared with the P10 RTL hit log). Pass = all +nreq requests replayed, 0 mismatching
// cycles, 0 X cycles, and the netlist's hit count equal to the RTL's.
`timescale 1ns / 1ps
module tb_gls_slice #(parameter COUNTER_MODE = 0, parameter CACHE_DEPTH = 256, parameter SEED = 1,
                      parameter MAXREQ = 200000);
localparam AW = 20, VW = 128;
reg clk = 0, rst_n = 0;
always #1 clk = ~clk;
reg req_valid = 0, fill_valid = 0;
reg [AW-1:0] req_addr = 0;
reg [VW-1:0] fill_data = 0;
wire rv_r, hf_r, fr_r, rv_g, hf_g, fr_g;
wire [VW-1:0] rd_r, rd_g;
wire [AW-1:0] fa_r, fa_g;
lfu_cache_controller #(.CACHE_DEPTH(CACHE_DEPTH), .COUNTER_MODE(COUNTER_MODE)) rtl (
    .clk(clk), .rst_n(rst_n), .req_valid(req_valid), .req_addr(req_addr),
    .resp_valid(rv_r), .resp_data(rd_r), .hit_flag(hf_r), .fill_req(fr_r), .fill_addr(fa_r),
    .fill_valid(fill_valid), .fill_data(fill_data));
lfu_cache_controller_gl gl (
    .clk(clk), .rst_n(rst_n), .req_valid(req_valid), .req_addr(req_addr),
    .resp_valid(rv_g), .resp_data(rd_g), .hit_flag(hf_g), .fill_req(fr_g), .fill_addr(fa_g),
    .fill_valid(fill_valid), .fill_data(fill_data));
integer cyc = 0, seed = SEED, d, k = 0, nreq = 0;
integer m_hf = 0, m_rv = 0, m_rd = 0, m_fr = 0, m_fa = 0, mism = 0, x_g = 0, x_r = 0;
integer n_resp = 0, n_hit = 0, n_miss = 0, g_resp = 0, g_hit = 0;
reg [AW-1:0] trace [0:MAXREQ-1];
reg [8*256-1:0] trace_file, hitlog_file;
integer hl = 0;
function integer rnd(input integer unused);
    rnd = $random(seed) & 32'h7fffffff;
endfunction
always @(posedge clk) if (rst_n) begin
    cyc = cyc + 1;
    if (hf_r !== hf_g) m_hf = m_hf + 1;
    if (rv_r !== rv_g) m_rv = m_rv + 1;
    if (rd_r !== rd_g) m_rd = m_rd + 1;
    if (fr_r !== fr_g) m_fr = m_fr + 1;
    if (fa_r !== fa_g) m_fa = m_fa + 1;
    if ({hf_r, rv_r, rd_r, fr_r, fa_r} !== {hf_g, rv_g, rd_g, fr_g, fa_g}) begin
        mism = mism + 1;
        if (mism <= 10) $display("MISMATCH cycle %0d request %0d: rtl hf=%b rv=%b fr=%b fa=%h rd=%h | gl hf=%b rv=%b fr=%b fa=%h rd=%h",
                                 cyc, k, hf_r, rv_r, fr_r, fa_r, rd_r, hf_g, rv_g, fr_g, fa_g, rd_g);
    end
    if ((^{hf_g, rv_g, rd_g, fr_g, fa_g}) === 1'bx) begin
        x_g = x_g + 1;
        if (x_g <= 5) $display("X/Z ON NETLIST OUTPUT cycle %0d", cyc);
    end
    if ((^{hf_r, rv_r, rd_r, fr_r, fa_r}) === 1'bx) begin
        x_r = x_r + 1;
        if (x_r <= 5) $display("X/Z ON RTL OUTPUT cycle %0d", cyc);
    end
    if (rv_r) n_resp = n_resp + 1;
    if (rv_r && hf_r) n_hit = n_hit + 1;
    if (rv_r && !hf_r) n_miss = n_miss + 1;
    if (rv_g) g_resp = g_resp + 1;
    if (rv_g && hf_g) g_hit = g_hit + 1;
    // progress, so a run stopped by the time limit still records how far it got
    if (cyc % 50000 == 0)
        begin $display("cycles compared %0d, requests %0d, mismatches %0d (x_cycles netlist %0d, rtl %0d)", cyc, k, mism, x_g, x_r); $fflush; end
end
initial begin
    if (!$value$plusargs("trace=%s", trace_file)) $fatal(1, "needs +trace=<file>");
    if (!$value$plusargs("nreq=%d", nreq)) $fatal(1, "needs +nreq=<requests in the file>");
    $readmemh(trace_file, trace, 0, nreq - 1);
    if ($value$plusargs("hitlog=%s", hitlog_file)) hl = $fopen(hitlog_file, "w");
    repeat (3) @(negedge clk);
    rst_n = 1;
    while (k < nreq) begin
        req_valid = 1; req_addr = trace[k];
        @(negedge clk);
        req_valid = 0;
        while (!rv_r && !fr_r) @(negedge clk);
        if (fr_r) begin
            d = rnd(0) % 4;
            repeat (d) @(negedge clk);
            fill_valid = 1; fill_data = {rnd(0), rnd(0), rnd(0), rnd(0)};
            @(negedge clk);
            fill_valid = 0;
            while (!rv_r) @(negedge clk);
        end
        if (hl) $fwrite(hl, "%0d %05h %0d\n", k, trace[k], hf_r);
        k = k + 1;
    end
    @(posedge clk); #0.1;   // count the last response (responses are counted on the edge after they appear)
    $display("gls_slice depth=%0d mode=%0d cycles=%0d requests=%0d responses=%0d hits=%0d misses=%0d gl_responses=%0d gl_hits=%0d mismatching_cycles=%0d hit_flag=%0d resp_valid=%0d resp_data=%0d fill_req=%0d fill_addr=%0d x_cycles_netlist=%0d x_cycles_rtl=%0d",
             CACHE_DEPTH, COUNTER_MODE, cyc, k, n_resp, n_hit, n_miss, g_resp, g_hit, mism, m_hf, m_rv, m_rd, m_fr, m_fa, x_g, x_r);
    if (hl) $fclose(hl);
    if (k == nreq && mism == 0 && x_g == 0 && x_r == 0 && g_hit == n_hit && g_resp == n_resp) $display("GLS SLICE LOCKSTEP PASSED");
    else                                                                                     $display("GLS SLICE LOCKSTEP FAILED");
    $finish;
end
endmodule
